class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int missingSum = mean * (rolls.length + n);
        for (int roll : rolls) {
            missingSum -= roll;
        }
        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int[] result = new int[n];
        int base = missingSum / n;
        int extra = missingSum % n;
        for (int i = 0; i < n; i++) {
            result[i] = base + (i < extra ? 1 : 0);
        }
        return result;
    }
}

class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int missingSum = mean * (rolls.length + n);
        for (int roll : rolls) {
            missingSum -= roll;
        }
        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int[] result = new int[n];
        java.util.Arrays.fill(result, 1);
        int remaining = missingSum - n;
        for (int i = 0; i < n && remaining > 0; i++) {
            int add = Math.min(5, remaining);
            result[i] += add;
            remaining -= add;
        }
        return result;
    }
}

class Solution {
    public int[] missingRolls(int[] rolls, int mean, int n) {
        int missingSum = mean * (rolls.length + n);
        for (int roll : rolls) {
            missingSum -= roll;
        }
        if (missingSum < n || missingSum > 6 * n) {
            return new int[0];
        }

        int[] answer = new int[n];
        for (int i = 0; i < n; i++) {
            int remainingSlots = n - i - 1;
            int value = Math.max(1, missingSum - 6 * remainingSlots);
            answer[i] = value;
            missingSum -= value;
        }
        return answer;
    }
}

